mapper.select:
SELECT * FROM ( SELECT leave_id as todo_id, 'leave' as todo_type, leave_type as todo_title, leave_reason as todo_content, user_name as apply_user, apply_time, CASE WHEN approval_status = '1' THEN '0' ELSE '1' END as status, leave_id as related_id FROM oa_leave WHERE user_id = #{userId} AND del_flag = '0' UNION ALL SELECT reimb_id, 'reimbursement', reimb_type, reimb_reason, user_name, apply_time, CASE WHEN approval_status = '1' THEN '0' ELSE '1' END, reimb_id FROM oa_reimbursement WHERE user_id = #{userId} AND del_flag = '0' UNION ALL SELECT doc_id, 'incoming_doc', doc_title, COALESCE(summary, ''), COALESCE(handler_name, create_by), create_time, CASE WHEN status IN ('0','1') THEN '0' ELSE '1' END, doc_id FROM oa_incoming_doc WHERE del_flag = '0' AND status IN ('0','1') AND (handler_id = #{userId} OR handler_id IS NULL OR #{userId} = 1) UNION ALL SELECT doc_id, 'outgoing_doc', doc_title, COALESCE(summary, ''), COALESCE(sign_user_name, create_by), create_time, CASE WHEN status IN ('0','1') THEN '0' ELSE '1' END, doc_id FROM oa_outgoing_doc WHERE del_flag = '0' AND status IN ('0','1') AND (sign_user_id = #{userId} OR create_by = #{userName} OR #{userId} = 1) ) t
AND todo_title LIKE #{todoTitleLike}
AND status = #{status}
ORDER BY apply_time DESC
